import pytest
import json
from pathlib import Path
from validator import SwaggerSchemaValidator

# Load test data from JSON file
_here = Path(__file__).resolve().parent
_endpoint_data_path = _here / "pet.json"
with open(_endpoint_data_path, 'r') as f:
    _ENDPOINT_TEST_DATA = json.load(f)

_PARAM_CASES = _ENDPOINT_TEST_DATA
_PARAM_IDS = [f"{case['scenario']}" for case in _ENDPOINT_TEST_DATA]

@pytest.fixture(scope="session")
def swagger_validator():
    return SwaggerSchemaValidator("api.json")

@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_update_pet(api_client, swagger_validator, config_test_data, scenario_case):
    """
    Test updating a pet using the /pet endpoint.
    """
    # Merge scenario specific data with default test data
    test_data = {**config_test_data, **scenario_case}

    # Extracting required fields from test_data
    name = test_data.get("name")
    photoUrls = test_data.get("photoUrls")

    if not name or not photoUrls:
        pytest.skip("Required fields 'name' or 'photoUrls' are missing in test data.")

    # Prepare request data
    request_data = {
        "name": name,
        "photoUrls": photoUrls
    }
    if "id" in test_data:
        request_data["id"] = test_data["id"]
    if "category" in test_data:
        request_data["category"] = test_data["category"]
    if "tags" in test_data:
        request_data["tags"] = test_data["tags"]
    if "status" in test_data:
        request_data["status"] = test_data["status"]

    # Validate request before sending
    swagger_validator.validate_json(request_data, "Pet")

    # Make the PUT request to update the pet
    response = api_client.put("/pet", data=request_data)

    # Validate the response schema
    validation_result = swagger_validator.validate_schema_by_response(
        endpoint="/pet",
        method="put",
        status_code=str(test_data["statusCode"]),
        response=response
    )

    assert validation_result["valid"], validation_result.get("message", "Response schema validation failed")

    # Assert the response status code
    assert response.status_code == test_data["statusCode"], f"Expected {test_data['statusCode']}, got {response.status_code}"
